<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class SupplierBillLine extends Model { use HasUuids; protected $fillable=['tenant_id','supplier_bill_id','purchase_order_item_id','goods_receipt_item_id','variant_id','account_id','description','quantity','unit','unit_price','discount_amount','tax_amount','line_total']; protected function casts():array{return ['quantity'=>'decimal:6','unit_price'=>'decimal:6','discount_amount'=>'decimal:6','tax_amount'=>'decimal:6','line_total'=>'decimal:6'];} public function bill(){return $this->belongsTo(SupplierBill::class,'supplier_bill_id');} public function purchaseOrderItem(){return $this->belongsTo(PurchaseOrderItem::class);} public function goodsReceiptItem(){return $this->belongsTo(GoodsReceiptItem::class);} public function variant(){return $this->belongsTo(ProductVariant::class);} public function account(){return $this->belongsTo(ChartAccount::class,'account_id');} }
